package dev.folio.buildlogic

import org.gradle.api.Plugin
import org.gradle.api.Project
import org.gradle.api.plugins.JavaPluginExtension
import org.gradle.api.tasks.compile.JavaCompile
import org.gradle.kotlin.dsl.configure
import org.gradle.kotlin.dsl.dependencies
import org.gradle.kotlin.dsl.withType
import org.jetbrains.kotlin.gradle.dsl.JvmTarget
import org.jetbrains.kotlin.gradle.dsl.KotlinJvmProjectExtension

class JvmLibraryConventionPlugin : Plugin<Project> {
    override fun apply(target: Project) {
        with(target) {
            pluginManager.apply("org.jetbrains.kotlin.jvm")
            pluginManager.apply("folio.quality")
            extensions.configure<JavaPluginExtension> {
                sourceCompatibility = FOLIO_JAVA_VERSION
                targetCompatibility = FOLIO_JAVA_VERSION
            }
            tasks.withType<JavaCompile>().configureEach { options.release.set(FOLIO_JAVA_RELEASE) }
            extensions.configure<KotlinJvmProjectExtension> {
                compilerOptions.jvmTarget.set(JvmTarget.JVM_17)
                // Compile against the JDK 17 API even though JDK 21 runs the build (A-002).
                compilerOptions.freeCompilerArgs.add("-Xjdk-release=$FOLIO_JAVA_RELEASE")
            }
            dependencies {
                add("testImplementation", libs.bundle("unit-test"))
            }
        }
    }
}

package dev.folio.core.common

import kotlin.coroutines.cancellation.CancellationException

/** Result of an operation that can fail in an expected way (IO, parsing, permissions). */
sealed interface Outcome<out T> {
    /** The operation produced [value]. */
    data class Success<out T>(
        val value: T,
    ) : Outcome<T>

    /** The operation failed; [message] is for logs, [cause] keeps the original exception if any. */
    data class Failure(
        val message: String,
        val cause: Throwable? = null,
    ) : Outcome<Nothing>
}

/** Value on success, null on failure. */
fun <T> Outcome<T>.getOrNull(): T? = (this as? Outcome.Success)?.value

/** Transforms the success value, keeps failures. */
inline fun <T, R> Outcome<T>.map(transform: (T) -> R): Outcome<R> =
    when (this) {
        is Outcome.Success -> Outcome.Success(transform(value))
        is Outcome.Failure -> this
    }

/** Chains another fallible step. */
inline fun <T, R> Outcome<T>.flatMap(transform: (T) -> Outcome<R>): Outcome<R> =
    when (this) {
        is Outcome.Success -> transform(value)
        is Outcome.Failure -> this
    }

/** Runs [block] and turns exceptions into [Outcome.Failure]. Cancellation is rethrown, never swallowed. */
@Suppress("TooGenericExceptionCaught") // Boundary helper: every non-cancellation exception becomes a Failure.
inline fun <T> outcomeOf(
    failureMessage: String,
    block: () -> T,
): Outcome<T> =
    try {
        Outcome.Success(block())
    } catch (e: CancellationException) {
        throw e
    } catch (e: Exception) {
        Outcome.Failure(failureMessage, e)
    }

package dev.folio.core.common

/** One entry of a directory listing. Paths are relative to the FolioFs root, '/'-separated. */
data class FsEntry(
    val path: String,
    val isDirectory: Boolean,
    val sizeBytes: Long,
    val modifiedMs: Long,
)

/**
 * File access below one root (the library folder in the app, a temp dir in tests).
 * Paths are relative to the root and '/'-separated ("" is the root). Absolute paths, '\\' and ".."
 * segments are programmer errors and throw IllegalArgumentException in every method.
 * Calls block: run them on FolioDispatchers.io.
 */
interface FolioFs {
    /** True if a file or directory exists at [path]. */
    fun exists(path: String): Boolean

    /** Direct children of [dir] ("" is the root). */
    fun list(dir: String): Outcome<List<FsEntry>>

    /** Whole file content. */
    fun readBytes(path: String): Outcome<ByteArray>

    /**
     * Atomic write (file-format-storage rule): unique temp file in the same directory, flush + fsync,
     * then rename over [path]. Readers never see a partial file; the temp file is removed on failure.
     * Creates parent dirs.
     */
    fun writeBytesAtomic(
        path: String,
        bytes: ByteArray,
    ): Outcome<Unit>

    /** Moves or renames; fails if [to] exists. Creates parent dirs of [to]. */
    fun move(
        from: String,
        to: String,
    ): Outcome<Unit>

    /** Deletes a file or an empty directory. Deleting a missing path succeeds. */
    fun delete(path: String): Outcome<Unit>

    /** Creates [dir] and its parents. */
    fun mkdirs(dir: String): Outcome<Unit>
}

