package dev.folio.core.model.geometry

import kotlin.math.abs
import kotlin.math.cos
import kotlin.math.max
import kotlin.math.min
import kotlin.math.sin

/**
 * 2D affine transform in page space: x' = a*x + c*y + tx, y' = b*x + d*y + ty
 * (the column order of android.graphics.Matrix: [a c tx; b d ty; 0 0 1]).
 */
data class Affine(
    val a: Float,
    val b: Float,
    val c: Float,
    val d: Float,
    val tx: Float,
    val ty: Float,
) {
    /** Determinant of the linear part. */
    val determinant: Float get() = (a.toDouble() * d - b.toDouble() * c).toFloat()

    /** True if the transform can be inverted. */
    val isInvertible: Boolean get() = abs(determinant) > MIN_DETERMINANT

    /** `this ∘ other`: the result maps p to `this.map(other.map(p))` (apply [other] first). */
    fun compose(other: Affine): Affine =
        Affine(
            a = a * other.a + c * other.b,
            b = b * other.a + d * other.b,
            c = a * other.c + c * other.d,
            d = b * other.c + d * other.d,
            tx = a * other.tx + c * other.ty + tx,
            ty = b * other.tx + d * other.ty + ty,
        )

    /** Applies this transform after [first]; same as `compose(first)`. Reads left to right in pipelines. */
    fun after(first: Affine): Affine = compose(first)

    /** The inverse transform. Throws for singular transforms (programmer error; check [isInvertible]). */
    fun invert(): Affine {
        val det = a.toDouble() * d - b.toDouble() * c
        require(abs(det) > MIN_DETERMINANT) { "Affine is not invertible: $this" }
        val ia = d / det
        val ib = -b / det
        val ic = -c / det
        val id = a / det
        return Affine(
            a = ia.toFloat(),
            b = ib.toFloat(),
            c = ic.toFloat(),
            d = id.toFloat(),
            tx = (-(ia * tx + ic * ty)).toFloat(),
            ty = (-(ib * tx + id * ty)).toFloat(),
        )
    }

    /** Maps x of point (x, y). */
    fun mapX(
        x: Float,
        y: Float,
    ): Float = a * x + c * y + tx

    /** Maps y of point (x, y). */
    fun mapY(
        x: Float,
        y: Float,
    ): Float = b * x + d * y + ty

    /** Maps a point. */
    fun mapPoint(p: PointPt): PointPt = PointPt(mapX(p.x, p.y), mapY(p.x, p.y))

    /** Axis-aligned bounds of the mapped rect (all four corners). */
    fun mapRect(r: RectPt): RectPt {
        if (r.isEmpty) return r
        val x0 = mapX(r.left, r.top)
        val y0 = mapY(r.left, r.top)
        val x1 = mapX(r.right, r.top)
        val y1 = mapY(r.right, r.top)
        val x2 = mapX(r.right, r.bottom)
        val y2 = mapY(r.right, r.bottom)
        val x3 = mapX(r.left, r.bottom)
        val y3 = mapY(r.left, r.bottom)
        return RectPt(
            min(min(x0, x1), min(x2, x3)),
            min(min(y0, y1), min(y2, y3)),
            max(max(x0, x1), max(x2, x3)),
            max(max(y0, y1), max(y2, y3)),
        )
    }

    /** Factories. */
    companion object {
        private const val MIN_DETERMINANT = 1e-12

        /** The identity transform. */
        val IDENTITY = Affine(1f, 0f, 0f, 1f, 0f, 0f)

        /** Translation by (dx, dy). */
        fun translate(
            dxPt: Float,
            dyPt: Float,
        ): Affine = Affine(1f, 0f, 0f, 1f, dxPt, dyPt)

        /** Scale by (sx, sy) around the pivot (px, py). */
        fun scale(
            sx: Float,
            sy: Float,
            pivotX: Float = 0f,
            pivotY: Float = 0f,
        ): Affine = Affine(sx, 0f, 0f, sy, pivotX - sx * pivotX, pivotY - sy * pivotY)

        /** Rotation by [angleDeg] (clockwise on screen, y down) around the pivot (px, py). */
        fun rotate(
            angleDeg: Float,
            pivotX: Float = 0f,
            pivotY: Float = 0f,
        ): Affine {
            val rad = Math.toRadians(angleDeg.toDouble())
            val cosV = cos(rad).toFloat()
            val sinV = sin(rad).toFloat()
            return Affine(
                a = cosV,
                b = sinV,
                c = -sinV,
                d = cosV,
                tx = pivotX - cosV * pivotX + sinV * pivotY,
                ty = pivotY - sinV * pivotX - cosV * pivotY,
            )
        }
    }
}

package dev.folio.core.model.geometry

import com.google.common.truth.Truth.assertThat
import com.google.common.truth.Truth.assertWithMessage
import org.junit.Assert.assertThrows
import org.junit.Test
import kotlin.math.abs
import kotlin.random.Random

class AffineTest {
    @Test
    fun composeInvert_randomTransforms_roundTripWithin1e4() {
        val random = Random(SEED)
        repeat(1000) { i ->
            val m = randomAffine(random)
            val msg = "seed=$SEED i=$i m=$m"
            assertIdentity(m.compose(m.invert()), msg)
            assertIdentity(m.invert().compose(m), msg)
            val p = PointPt(random.nextFloat() * 400f - 200f, random.nextFloat() * 400f - 200f)
            val back = m.invert().mapPoint(m.mapPoint(p))
            assertWithMessage(msg).that(back.x).isWithin(TOL).of(p.x)
            assertWithMessage(msg).that(back.y).isWithin(TOL).of(p.y)
        }
    }

    @Test
    fun compose_appliesArgumentFirst() {
        val t = Affine.translate(10f, 0f)
        val s = Affine.scale(2f, 2f)
        // scale after translate: (1, 0) -> (11, 0) -> (22, 0)
        assertThat(s.compose(t).mapPoint(PointPt(1f, 0f))).isEqualTo(PointPt(22f, 0f))
        assertThat(t.compose(s).mapPoint(PointPt(1f, 0f))).isEqualTo(PointPt(12f, 0f))
        assertThat(s.after(t)).isEqualTo(s.compose(t))
    }

    @Test
    fun rotate_90DegAroundPivot_turnsClockwiseOnScreen() {
        val r = Affine.rotate(90f, 10f, 10f)
        val p = r.mapPoint(PointPt(20f, 10f))
        assertThat(p.x).isWithin(TOL).of(10f)
        assertThat(p.y).isWithin(TOL).of(20f)
    }

    @Test
    fun scale_aroundPivot_keepsPivotFixed() {
        val p = Affine.scale(3f, 0.5f, 7f, 9f).mapPoint(PointPt(7f, 9f))
        assertThat(p).isEqualTo(PointPt(7f, 9f))
    }

    @Test
    fun mapRect_rotation45_returnsAxisAlignedBounds() {
        val r = Affine.rotate(45f, 0f, 0f).mapRect(RectPt(-1f, -1f, 1f, 1f))
        val h = 1.4142135f
        assertThat(r.left).isWithin(TOL).of(-h)
        assertThat(r.top).isWithin(TOL).of(-h)
        assertThat(r.right).isWithin(TOL).of(h)
        assertThat(r.bottom).isWithin(TOL).of(h)
    }

    @Test
    fun invert_singular_throws() {
        val singular = Affine(1f, 2f, 2f, 4f, 0f, 0f)
        assertThat(singular.isInvertible).isFalse()
        assertThrows(IllegalArgumentException::class.java) { singular.invert() }
    }

    private fun randomAffine(random: Random): Affine {
        while (true) {
            val m =
                Affine(
                    a = random.nextFloat() * 4f - 2f,
                    b = random.nextFloat() * 4f - 2f,
                    c = random.nextFloat() * 4f - 2f,
                    d = random.nextFloat() * 4f - 2f,
                    tx = random.nextFloat() * 400f - 200f,
                    ty = random.nextFloat() * 400f - 200f,
                )
            if (abs(m.determinant) > 0.25f) return m
        }
    }

    private fun assertIdentity(
        m: Affine,
        msg: String,
    ) {
        assertWithMessage(msg).that(m.a).isWithin(TOL).of(1f)
        assertWithMessage(msg).that(m.b).isWithin(TOL).of(0f)
        assertWithMessage(msg).that(m.c).isWithin(TOL).of(0f)
        assertWithMessage(msg).that(m.d).isWithin(TOL).of(1f)
        assertWithMessage(msg).that(m.tx).isWithin(TOL).of(0f)
        assertWithMessage(msg).that(m.ty).isWithin(TOL).of(0f)
    }

    private companion object {
        const val SEED = 20260928
        const val TOL = 1e-4f
    }
}

