) : EditCommand {
    override val requiredPages: Set<PageId> get() = emptySet()

    override fun execute(doc: Document): Applied {
        val putIds = put.map { it.id }.toHashSet()
        require(putIds.size == put.size && remove.none { it in putIds }) { "flow id listed twice" }
