/** Generates a random valid command for a document whose pages are all loaded. */
internal class RandomCommands(
    private val random: Random,
) {
    fun next(doc: Document): EditCommand {
        if (random.nextInt(BATCH_ONE_IN) == 0) return batch(doc)
        return single(doc)
    }

    private fun batch(doc: Document): EditCommand {
        var current = doc
        val commands = List(2 + random.nextInt(2)) {
            single(current).also { current = it.execute(current).doc }
        }
        return Batch(commands)
    }

    @Suppress("CyclomaticComplexMethod") // One branch per command type keeps the generator readable.
    private fun single(doc: Document): EditCommand {
        val ref = doc.pages[random.nextInt(doc.pages.size)]
        val page = doc.pageBodies.getValue(ref.id)
        val objects = page.objects
        return when (random.nextInt(COMMAND_KINDS)) {
            0 -> AddObjects(ref.id, List(1 + random.nextInt(3)) { ModelFixtures.randomObject(random) }, randomIndexOrNull(objects.size))
            1 -> if (objects.isEmpty()) single(doc) else RemoveObjects(ref.id, subset(objects.map { it.id }))
            2 ->
                ReplaceObjects(
                    ref.id,
                    if (objects.isEmpty()) emptyList() else subset(objects.map { it.id }),
                    List(random.nextInt(3)) { ModelFixtures.randomObject(random) },
                )
            3 -> if (objects.isEmpty()) single(doc) else TransformObjects(ref.id, subset(objects.map { it.id }), randomAffine())
            4 -> if (objects.isEmpty()) single(doc) else RecolorObjects(ref.id, subset(objects.map { it.id }), random.nextInt())
            5 ->
                if (objects.isEmpty()) {
                    single(doc)
                } else {
                    ReorderObjects(ref.id, subset(objects.map { it.id }), ReorderOp.entries[random.nextInt(ReorderOp.entries.size)])
                }
            6 -> editFlow(doc)
            7 -> InsertPages(random.nextInt(doc.pages.size + 1), listOf(ModelFixtures.randomPage(random, random.nextInt(4))))
            8 -> if (doc.pages.size < 2) single(doc) else RemovePages(listOf(ref.id))
            9 -> MovePages(subset(doc.pages.map { it.id }), random.nextInt(doc.pages.size))
            10 -> UpdatePageSpec(ref.id, randomSpec())
            11 -> UpdateBackground(ref.id, page.background.copy(paperArgb = random.nextInt()))
            12 ->
                UpdateMeta(
                    doc.meta.copy(
                        title = "T${random.nextInt(1000)}",
                        favorite = random.nextBoolean(),
                        tags = List(random.nextInt(3)) { "tag${random.nextInt(5)}" }.toPersistentSet(),
                    ),
                )
            13 -> updateFlows(doc)
            else -> updateAssets(doc)
        }
    }

    private fun editFlow(doc: Document): EditCommand {
        if (doc.flows.isEmpty()) return UpdateFlows(listOf(ModelFixtures.flow(ModelFixtures.randomId(random), "hello")))
