package dev.folio.core.format.codec

import dev.folio.core.common.Outcome
import dev.folio.core.format.FormatError
import dev.folio.core.model.AssetId
import dev.folio.core.model.Attachment
import dev.folio.core.model.Background
import dev.folio.core.model.BrushSpec
import dev.folio.core.model.FlowFrame
import dev.folio.core.model.FlowId
import dev.folio.core.model.ImageObject
import dev.folio.core.model.InkStroke
import dev.folio.core.model.ObjectId
import dev.folio.core.model.Page
import dev.folio.core.model.PageId
import dev.folio.core.model.PageObject
import dev.folio.core.model.PageSpec
import dev.folio.core.model.PdfBackground
import dev.folio.core.model.RectF01
import dev.folio.core.model.Shape
import dev.folio.core.model.StickyNote
import dev.folio.core.model.StrokeStyle
import dev.folio.core.model.Template
import dev.folio.core.model.geometry.PointPt
import dev.folio.core.model.geometry.RectPt
import kotlinx.collections.immutable.toPersistentList
import java.io.IOException
import dev.folio.core.format.proto.v1.Attachment as PbAttachment
import dev.folio.core.format.proto.v1.Background as PbBackground
import dev.folio.core.format.proto.v1.BrushSpec as PbBrushSpec
import dev.folio.core.format.proto.v1.Custom as PbCustom
import dev.folio.core.format.proto.v1.Fixed as PbFixed
import dev.folio.core.format.proto.v1.FlowFrame as PbFlowFrame
import dev.folio.core.format.proto.v1.Image as PbImage
import dev.folio.core.format.proto.v1.Infinite as PbInfinite
import dev.folio.core.format.proto.v1.InkStroke as PbInkStroke
import dev.folio.core.format.proto.v1.Page as PbPage
import dev.folio.core.format.proto.v1.PageObject as PbPageObject
import dev.folio.core.format.proto.v1.PageSpec as PbPageSpec
import dev.folio.core.format.proto.v1.PdfBackground as PbPdfBackground
import dev.folio.core.format.proto.v1.Point as PbPoint
import dev.folio.core.format.proto.v1.Rect as PbRect
import dev.folio.core.format.proto.v1.Shape as PbShape
import dev.folio.core.format.proto.v1.StickyNote as PbStickyNote
import dev.folio.core.format.proto.v1.StrokeStyle as PbStrokeStyle
import dev.folio.core.format.proto.v1.Template as PbTemplate

/** Page body <-> `pages/<pageId>.pb` (folio.v1.Page). */
object PageCodec {
    /** Protobuf bytes of [page] (before DEFLATE). */
    fun encode(page: Page): ByteArray = PbPage.ADAPTER.encode(toProto(page))

    /**
     * Decodes untrusted bytes. Failures carry [FormatError.Corrupt] for [entry]. Objects of kinds this
     * version does not know (newer writer) are skipped.
     */
    fun decode(
        bytes: ByteArray,
        entry: String,
    ): Outcome<Page> =
        try {
            Outcome.Success(fromProto(PbPage.ADAPTER.decode(bytes)))
        } catch (e: IOException) {
            corrupt(entry, "unreadable protobuf", e)
        } catch (e: CorruptDataException) {
            corrupt(entry, e.message.orEmpty(), e)
        } catch (e: IllegalArgumentException) {
            // Wire's generated constructors and model init blocks validate with require().
            corrupt(entry, e.message.orEmpty(), e)
        }

    private fun corrupt(
        entry: String,
        detail: String,
        cause: Throwable,
    ): Outcome.Failure = Outcome.Failure("cannot decode $entry: $detail", FormatError.Corrupt(entry, detail, cause))

    internal fun toProto(page: Page): PbPage =
        PbPage(
            id = page.id.value,
            spec = specToProto(page.spec),
            background = backgroundToProto(page.background),
            objects = page.objects.map(::objectToProto),
            content_bounds = if (page.spec is PageSpec.Infinite) page.contentBounds()?.let(::rectToProto) else null,
        )

    internal fun fromProto(pb: PbPage): Page {
        corruptIf(pb.id.isBlank()) { "page id missing" }
        val spec = pb.spec?.let(::specFromProto) ?: throw CorruptDataException("page spec missing")
        val background = pb.background?.let(::backgroundFromProto) ?: throw CorruptDataException("background missing")
        val objects = pb.objects.mapNotNull(::objectFromProto)
        corruptIf(objects.distinctBy { it.id }.size != objects.size) { "duplicate object ids" }
        return Page(PageId(pb.id), spec, background, objects.toPersistentList())
    }

    private fun specToProto(spec: PageSpec): PbPageSpec =
        when (spec) {
            is PageSpec.Fixed -> PbPageSpec(fixed = fixedToProto(spec))
            is PageSpec.Custom -> PbPageSpec(custom = PbCustom(spec.widthPt, spec.heightPt))
            is PageSpec.Infinite ->
                when (val origin = spec.origin) {
                    is PageSpec.Fixed -> PbPageSpec(infinite = PbInfinite(origin_fixed = fixedToProto(origin)))
                    is PageSpec.Custom -> PbPageSpec(infinite = PbInfinite(origin_custom = PbCustom(origin.widthPt, origin.heightPt)))
                    is PageSpec.Infinite -> error("nested infinite spec")
                }
        }

    private fun fixedToProto(spec: PageSpec.Fixed): PbFixed = PbFixed(EnumCodec.paperSize(spec.size), EnumCodec.orientation(spec.orientation))

    private fun specFromProto(pb: PbPageSpec): PageSpec {
        pb.fixed?.let { return fixedFromProto(it) }
        pb.custom?.let { return customFromProto(it) }
        val infinite = pb.infinite ?: throw CorruptDataException("page spec has no kind")
        infinite.origin_fixed?.let { return PageSpec.Infinite(fixedFromProto(it)) }
        infinite.origin_custom?.let { return PageSpec.Infinite(customFromProto(it)) }
        throw CorruptDataException("infinite page has no origin")
    }

    private fun fixedFromProto(pb: PbFixed): PageSpec.Fixed = PageSpec.Fixed(EnumCodec.paperSize(pb.size), EnumCodec.orientation(pb.orientation))

    private fun customFromProto(pb: PbCustom): PageSpec.Custom {
        corruptIf(!(pb.width_pt > 0f && pb.height_pt > 0f)) { "custom page size ${pb.width_pt} x ${pb.height_pt}" }
        return PageSpec.Custom(pb.width_pt, pb.height_pt)
    }

    private fun backgroundToProto(bg: Background): PbBackground =
        PbBackground(
            paper_argb = bg.paperArgb,
            template =
                PbTemplate(
                    kind = EnumCodec.templateKind(bg.template.kind),
                    spacing_pt = bg.template.spacingPt,
                    line_argb = bg.template.lineArgb,
                    margin_left_pt = bg.template.marginLeftPt,
