                            stroke = PbStrokeStyle(o.stroke.argb, o.stroke.widthPt, o.stroke.dashed),
                            fill_argb = o.fillArgb ?: 0,
                            has_fill = o.fillArgb != null,
                            bounds = rectToProto(o.bounds),
                        ),
                )
            is FlowFrame ->
                PbPageObject(
                    id = id,
                    frame = PbFlowFrame(o.flow.value, rectToProto(o.rect), o.order, EnumCodec.frameRole(o.role), o.autoGrow),
                )
            is ImageObject ->
                PbPageObject(
                    id = id,
                    image =
                        PbImage(
                            o.asset.value,
                            rectToProto(o.rect),
                            o.rotationDeg,
                            PbRect(o.crop.left, o.crop.top, o.crop.right, o.crop.bottom),
                        ),
                )
            is StickyNote -> PbPageObject(id = id, sticky = PbStickyNote(o.flow.value, rectToProto(o.rect), o.rotationDeg, o.argb))
            is Attachment ->
                PbPageObject(
                    id = id,
                    attachment = PbAttachment(o.asset.value, o.displayName, o.mime, PbPoint(o.position.x, o.position.y)),
                )
        }
    }

    private fun objectFromProto(pb: PbPageObject): PageObject? {
        corruptIf(pb.id.isBlank()) { "object id missing" }
        val id = ObjectId(pb.id)
        pb.stroke?.let { s ->
            val b = s.brush ?: throw CorruptDataException("brush missing")
            val inputs = StrokeCodec.decode(s.inputs ?: throw CorruptDataException("stroke inputs missing"))
            val brush = BrushSpec(EnumCodec.brushKind(b.kind), b.argb, b.size_pt, b.version, b.pressure_gamma)
            return InkStroke(id, brush, inputs, requireRect(s.bounds, "stroke bounds"))
        }
        pb.shape?.let { s ->
            val style = s.stroke ?: throw CorruptDataException("shape style missing")
            return Shape(
                id = id,
                kind = EnumCodec.shapeKind(s.kind),
                points = s.points.map { PointPt(it.x, it.y) },
                rotationDeg = s.rotation_deg,
                stroke = StrokeStyle(style.argb, style.width_pt, style.dashed),
                fillArgb = if (s.has_fill) s.fill_argb else null,
                bounds = requireRect(s.bounds, "shape bounds"),
            )
        }
        pb.frame?.let { f ->
            return FlowFrame(id, FlowId(f.flow_id), requireRect(f.rect, "frame rect"), f.order, EnumCodec.frameRole(f.role), f.auto_grow)
        }
        pb.image?.let { i ->
            val crop = i.crop?.let { RectF01(it.left, it.top, it.right, it.bottom) } ?: RectF01.FULL
            return ImageObject(id, AssetId(i.asset), requireRect(i.rect, "image rect"), i.rotation_deg, crop)
        }
        pb.sticky?.let { s ->
            return StickyNote(id, FlowId(s.flow_id), requireRect(s.rect, "sticky rect"), s.rotation_deg, s.argb)
        }
        pb.attachment?.let { a ->
            val p = a.position ?: throw CorruptDataException("attachment position missing")
            return Attachment(id, AssetId(a.asset), a.display_name, a.mime, PointPt(p.x, p.y))
        }
        return null
    }

    private fun rectToProto(r: RectPt): PbRect = PbRect(r.left, r.top, r.right, r.bottom)

    private fun requireRect(
        pb: PbRect?,
        what: String,
    ): RectPt = pb?.let { RectPt(it.left, it.top, it.right, it.bottom) } ?: throw CorruptDataException("$what missing")
}

