        PbFixed(EnumCodec.paperSize(spec.size), EnumCodec.orientation(spec.orientation))

    private fun specFromProto(pb: PbPageSpec): PageSpec {
        pb.fixed?.let { return fixedFromProto(it) }
        pb.custom?.let { return customFromProto(it) }
        val infinite = pb.infinite ?: throw CorruptDataException("page spec has no kind")
        infinite.origin_fixed?.let { return PageSpec.Infinite(fixedFromProto(it)) }
        infinite.origin_custom?.let { return PageSpec.Infinite(customFromProto(it)) }
        throw CorruptDataException("infinite page has no origin")
    }

