import dev.folio.core.format.proto.v1.Attachment as PbAttachment
import dev.folio.core.format.proto.v1.BrushSpec as PbBrushSpec
import dev.folio.core.format.proto.v1.FlowFrame as PbFlowFrame
import dev.folio.core.format.proto.v1.Image as PbImage
import dev.folio.core.format.proto.v1.InkStroke as PbInkStroke
import dev.folio.core.format.proto.v1.PageObject as PbPageObject
import dev.folio.core.format.proto.v1.Rect as PbRect
import dev.folio.core.format.proto.v1.Shape as PbShape
import dev.folio.core.format.proto.v1.StickyNote as PbStickyNote
import dev.folio.core.format.proto.v1.StrokeStyle as PbStrokeStyle

/** Page objects <-> proto. Unknown object kinds (all oneof members null) decode to null. */
internal object ObjectCodec {
    fun toProto(o: PageObject): PbPageObject {
        val id = o.id.value
        return when (o) {
            is InkStroke -> PbPageObject(id = id, stroke = strokeToProto(o))
            is Shape -> PbPageObject(id = id, shape = shapeToProto(o))
            is FlowFrame -> PbPageObject(id = id, frame = PbFlowFrame(o.flow.value, rectToProto(o.rect), o.order, EnumCodec.frameRole(o.role), o.autoGrow))
            is ImageObject -> {
                val crop = PbRect(o.crop.left, o.crop.top, o.crop.right, o.crop.bottom)
                PbPageObject(id = id, image = PbImage(o.asset.value, rectToProto(o.rect), o.rotationDeg, crop))
            }
            is StickyNote -> PbPageObject(id = id, sticky = PbStickyNote(o.flow.value, rectToProto(o.rect), o.rotationDeg, o.argb))
            is Attachment -> PbPageObject(id = id, attachment = PbAttachment(o.asset.value, o.displayName, o.mime, pointToProto(o.position)))
        }
    }

    fun fromProto(pb: PbPageObject): PageObject? {
        corruptIf(pb.id.isBlank()) { "object id missing" }
        val id = ObjectId(pb.id)
        val stroke = pb.stroke
        val shape = pb.shape
        val frame = pb.frame
        val image = pb.image
        val sticky = pb.sticky
        val attachment = pb.attachment
        return when {
            stroke != null -> strokeFromProto(id, stroke)
            shape != null -> shapeFromProto(id, shape)
            frame != null -> FlowFrame(id, FlowId(frame.flow_id), rectFromProto(frame.rect, "frame rect"), frame.order, EnumCodec.frameRole(frame.role), frame.auto_grow)
            image != null -> imageFromProto(id, image)
            sticky != null -> StickyNote(id, FlowId(sticky.flow_id), rectFromProto(sticky.rect, "sticky rect"), sticky.rotation_deg, sticky.argb)
            attachment != null ->
                Attachment(id, AssetId(attachment.asset), attachment.display_name, attachment.mime, pointFromProto(attachment.position.orCorrupt("attachment position")))
            else -> null
        }
    }

