            DocumentMeta(
                id = DocId(m.id),
                title = m.title,
                createdMs = m.createdMs,
                modifiedMs = m.modifiedMs,
                tags = m.tags.toPersistentSet(),
                favorite = m.favorite,
                formatVersion = m.formatVersion,
                defaultPageSpec = defaultSpec,
                defaultBackground = defaultBg,
